/* WILDPAW — texturas de las fotos vivas en data: URI.
   Generado a partir de assets/img/*.webp y assets/img/depth/*.png.
   WebGL no acepta imágenes cargadas desde file:// (doble clic en index.html),
   pero sí data: URI, por eso se incluyen aquí. */
window.WILDPAW = window.WILDPAW || {};
WILDPAW.livingPhotos = {
  dog: { color: 'data:image/webp;base64,', depth: 'data:image/png;base64,' },
  cat: { color: 'data:image/webp;base64,', depth: 'data:image/png;base64,' }
};
